// ---------- router ----------
// A BLANK PAGE IS NOT AN OUTCOME. Whatever goes wrong - a renderer that
// throws, a renderer that runs and paints nothing - the manager must be told
// and must be given somewhere to go. Silence here reads as "the game is
// broken" and leaves no way to find out otherwise.
function foPageFailed(where,err,why){
  try{
    const el=document.getElementById('page'); if(!el)return;
    if(el.querySelector('.fo-page-failed'))return;              // already saying it
    const detail=err?String((err&&err.message)||err).slice(0,300):'';
    el.innerHTML='<div class="fo-page-failed" style="max-width:560px;margin:52px auto;padding:22px 24px;border:1px solid rgba(0,0,0,.14);border-radius:14px;background:rgba(255,255,255,.92)">'+
      '<h3 style="margin:0 0 10px">This page did not draw</h3>'+
      '<p style="margin:0 0 14px;line-height:1.55">'+esc(why||'Something went wrong drawing this page.')+
      ' Nothing is lost — your club and everything it has done are safe on the server. Try another page, or reload.</p>'+
      (detail?'<pre style="margin:0 0 14px;padding:8px 10px;border-radius:8px;background:rgba(0,0,0,.05);font-size:11px;line-height:1.5;white-space:pre-wrap;overflow-x:auto">'+esc(detail)+'</pre>':'')+
      '<div style="display:flex;gap:8px;flex-wrap:wrap">'+
      '<button onclick="location.hash=\'#/squad\'">Squad</button>'+
      '<button onclick="location.hash=\'#/fixtures\'">Fixtures</button>'+
      '<button class="primary" onclick="location.reload()">Reload</button></div></div>';
  }catch(e){}
}
// Some renderers paint on their own interval rather than during route(), so a
// page that is empty for an instant is normal. One that is STILL empty seconds
// later, with the route unchanged, is not.
let foBlankT=null;
function foBlankWatch(where){
  try{
    clearTimeout(foBlankT);
    foBlankT=setTimeout(function(){
      try{
        const el=document.getElementById('page');
        if(!el||App.page!==where)return;                        // moved on; not our business
        if(el.firstElementChild)return;                         // something drew
        console.error('route drew nothing on '+where);
        foPageFailed(where,null,'The '+where+' page finished loading but drew nothing.');
      }catch(e){}
    },5000);
  }catch(e){}
}
function route(){
  try{
  // an empty hash becomes a real #/circuit hash (not just a default) so the
  // overlay page renderers - which gate on location.hash - actually paint
  if(!location.hash){location.hash='#/home';return}
  const h=location.hash;
  const [path,qs]=h.slice(2).split('?');
  const q={};if(qs)for(const kv of qs.split('&')){const [k,v]=kv.split('=');q[k]=decodeURIComponent(v||'')}
  App.page=path||'circuit';
  // The Table was a second league table, and two tables that could disagree
  // is worse than one. The league page is the table now; old links follow.
  if(App.page==='table'){location.hash='#/league';return}
  foSyncMyIx();   // one club per device, before a single page paints
  // Circuit-only era: the club dashboard and the league/office/training
  // surfaces are retired; any old link or bookmark lands on the Circuit.
  // training returned to life as The Nets (league/18-training-nets.js)
  // RETIRED ROOMS. Two waves: the Circuit-era surfaces (the club dashboard, the
  // office, the old stats and match pages) and the rooms taken out on
  // request - the time machine, the manual, the season so far, the wire, the
  // record book, the invitationals, the world-club page, the transfer market,
  // the books, the dossier and the desk. Every old address, bookmark and
  // in-game link lands on the front door rather than a blank screen.
  // #/stats came OFF this list: the Circuit-era averages page it used to name
  // is still retired, but the address now opens the STATS CENTRE, which reads
  // the served world's scorebook instead of this device's own.
  const GONE={club:1,office:1,nets:1,matches:1,transfers:1,story:1,friendly:1,scout:1,reports:1,commentary:1,calibration:1,editor:1,welcome:1,founder:1,create:1,
    whatif:1,guide:1,manual:1,help:1,ceremony:1,wire:1,records:1,comps:1,worldclub:1,ledger:1,dossier:1,desk:1};
  if(GONE[App.page]){location.hash='#/home';App.page='home';return}
  // the conquest Circuit is retired; its hub folds into the repurposed World map
  if(App.page==='circuit'||App.page==='tour'){location.hash='#/world';App.page='world';return}
  /* THE GATE USED TO ASK THE DEVICE, AND THE DEVICE ANSWERED FOR ITSELF.
     fo_welcomed was set by the solo front door - name a club, play - so it
     meant "this browser has started a career". With the career moved to the
     world, nothing sets it, and a manager signed in on a fresh phone would
     have been bounced back to the club home from every single page.
     What the gate is actually for is: do not let somebody wander the club
     rooms before they hold a club. So it asks the WORLD that question now. */
  try{
    var seated=false;
    try{seated=!!(window.__foWorldClaim||JSON.parse(localStorage.getItem('fo_world_claim')||'null')||(window.__foJWT&&window.__foJWT()))}catch(eS){}
    // the rooms anybody may read: the world is public, only a club is not
    var OPEN={home:1,league:1,nation:1,world:1,planet:1,rankings:1,nations:1,natteams:1,
              stats:1,schedule:1,almanack:1,atlas:1,champions:1,facup:1,colts:1,watch:1,
              feed:1,live:1,paper:1,lore:1,star:1,team:1,player:1,manual:1,help:1};
    if(!seated && !OPEN[App.page]){ location.hash='#/home'; return; }
  }catch(e){}
  // Squad Intelligence stopped being a page of its own: it is the third way to
  // read the squad, beside the Roster and the Grid, and it lives at #/squad.
  // Links and bookmarks made while it had its own address still work.
  if(App.page==='squad-intelligence'){
    try{localStorage.setItem('fo_sq_view','int')}catch(e){}
    try{(window.squadView=window.squadView||{}).view='int'}catch(e){}
    location.hash='#/squad';return
  }
  document.querySelectorAll('#topbar a').forEach(a=>a.classList.toggle('on',a.dataset.nav===App.page));
  /* THE ROUTE TABLE IS THE DOOR LIST, and the solo career's doors are off it.
     What survives is what the served world still uses: the squad, the orders
     sheet, a player's page, and the live match room the world theatre rejoins
     a broadcast through. Everything else that used to be named on this line -
     the club dashboard, the office, the solo market, the solo fixture list,
     the on-device averages page, the draft, the tour - was reachable only from
     a career this game no longer offers, and is now reachable from nowhere.

     THE BODIES ARE STILL IN THE FILE, and that is a deliberate stop rather
     than laziness. Three attempts to cut them out each broke multiplayer in a
     different place, every one caught by the tests:

       - cutting from one page to the next swallowed findPlayer and the aggBat
         family, which the market and the player page call;
       - runTour is not a tour. FO_TRAIN_PROGS, FO_TRAIN_FOCUS, FO_PLAN_ENTRY,
         foSetIntensity and foBulkTrain all live inside it, and the nets page
         is very much a multiplayer room;
       - pgMatch and renderMatch are not solo either: the world theatre rejoins
         a live served broadcast through them.

     The solo code is braided through the shared code rather than sitting
     beside it, so pulling it out is an incremental job with a test after every
     step - not one sweep. Closing the doors is the safe half of it, and it is
     done: nothing below can be reached. */
  const P={squad:pgSquad,orders:pgOrders,player:pgPlayer,match:pgMatch,scorecard:pgScorecard};
  // Circuit-era pages paint themselves; dispatch them directly so a refresh
  // never flashes the retired club dashboard while their interval spins up
  const OV={home:'foRenderHome',market:'foRenderMarketPage',league:'foRenderLeagueTablePage',nation:'foRenderNation',atlas:'foRenderLeague',planet:'foRenderPlanetPage',almanack:'foRenderAlmanackPage',star:'foRenderStarPage',wcmatch:'foRenderWcMatchPage',cup:'foRenderCup',circuit:'foRenderCircuit',city:'foRenderCity',tour:'foRenderTour',world:'foRenderWorld',boss:'foRenderBoss',side:'foRenderSide',lore:'foRenderLore',report:'foRenderReport',preview:'foRenderPreviewPage',training:'foRenderNetsPage',milestones:'foRenderHonoursPage',fixtures:'foRenderFixturesPage',matchday:'foRenderMatchdayPage',paper:'foRenderPaperPage',champions:'foRenderChampionsPage',facup:'foRenderFaCupPage',natteams:'foRenderNationsPage',nations:'foRenderNationsPage',watch:'foRenderWatchPage',feed:'foRenderFeedPage',live:'foRenderLiveScores',rankings:'foRenderRankingsPage',team:'foRenderClubPage',academy:'foRenderAcademyPage',finance:'foRenderFinancePage',ground:'foRenderGroundPage',schedule:'foRenderSchedulePage',stats:'foRenderStatsPage',statement:'foRenderStatementPage',news:'foRenderNewsPage'}[App.page];
  if(P[App.page])P[App.page](q);
  // A RENDERER THAT THROWS USED TO VANISH. This catch was empty, so a page
  // whose painter hit an error left the topbar, the clock and the nav in place
  // over an entirely blank body - no message, no console line anyone would
  // think to look for, no way out. Report it, and put something on the screen
  // that says what happened and offers somewhere else to go.
  else if(OV&&typeof window[OV]==='function'){try{window[OV]()}catch(eOv){
    try{console.error('route renderer failed on '+App.page,eOv)}catch(e3){}
    foPageFailed(App.page,eOv,'The '+App.page+' page hit an error while drawing.');
  }}
  else if(OV){/* overlay not parsed yet: leave the page blank, its interval paints */}
  else{location.hash='#/home';return}
  foBlankWatch(App.page);
  }catch(eRoute){
    // a broken page renderer must not freeze navigation for the whole session
    try{console.error('route failed on '+(App&&App.page),eRoute)}catch(e2){}
    try{foPageFailed(App&&App.page,eRoute,'This page could not be opened.')}catch(e4){}
  }finally{
    // first-class post-route hook: the league layer decorates the page here
    if(typeof window!=='undefined'&&typeof window.foAfterRoute==='function'){try{window.foAfterRoute()}catch(eAR){}}
  }
}
