function exportSession(){
  const data=JSON.stringify({results:App.results.map(r=>({date:r.date,home:r.home,away:r.away,ground:r.ground,seed:r.seed,pitch:r.pitch,result:r.result})),teams:GD.teams});
  const a=document.createElement('a');a.href='data:application/json,'+encodeURIComponent(data);a.download='fifty-overs-session.json';a.click();
}
function importSession(inp){const f=inp.files[0];if(!f)return;const rd=new FileReader();
  rd.onload=()=>{try{const d=JSON.parse(rd.result);if(d.teams)GD.teams=d.teams;alert('Imported teams. (Full match replays not restorable from export.)');route()}catch(e){alert('Bad file')}};rd.readAsText(f)}

// ---------- Squad ----------
let squadView={display:'Summary',sort:'Rating',key:null,dir:1,showY:false,showS:true,open:{}};
function sortPlayers(ps){
  const k=squadView.sort;
  const f={'Rating':p=>-p.rating,'Age':p=>p.age,'Batting':p=>-aggBat(p),'Bowling':p=>-aggBowl(p),'Fielding':p=>-aggField(p),'Wage':p=>-p.wage,'Form':p=>p.formWord}[k]||(p=>-p.rating);
  return ps.slice().sort((a,b)=>{const x=f(a),y=f(b);return x<y?-1:x>y?1:0});
}
function pgSquad(){
  const t=userTeam();
  let pool=[];if(squadView.showS)pool=pool.concat(t.players);
  if(squadView.showY)pool=pool.concat((t.youth||[]).map(p=>Object.assign({__y:true},p)));
  const ps=sortPlayers(pool);
  const ctl=`<div class="ctlrow">
    <span>Squad: <b>${t.players.length}</b></span>
    <label><input type="checkbox" ${squadView.showS?'checked':''} onchange="squadView.showS=this.checked;pgSquad()"> Show Seniors</label>

    <span>Display:</span><select onchange="squadView.display=this.value;pgSquad()">${['Summary','Overall Grid','Batting','Bowling','Fielding'].map(o=>`<option ${o===squadView.display?'selected':''}>${o}</option>`).join('')}</select>
    <span>Sort:</span><select onchange="squadView.sort=this.value;pgSquad()">${['Rating','Age','Batting','Bowling','Fielding','Form'].map(o=>`<option ${o===squadView.sort?'selected':''}>${o}</option>`).join('')}</select>
    <a href="#/editor" class="small">team editor</a></div>`;
  let body='';
  if(squadView.display==='Overall Grid')body=gridTable(ps);
  else if(squadView.display==='Summary')body=ps.map(summaryBlock).join('');
  else{
    const cols={'Batting':['vsPace','vsSpin','power','rotation','temperament'],
      'Bowling':['wicket','economy','discipline','moveTurn','variation','stamina'],
      'Fielding':['fielding','catching','keeping','stumping']}[squadView.display];
    body=ps.map(p=>`<div class="pblock"><div class="hd"><span title="${esc(p.nat)}">${flag(p.nat)}</span> ${playerLink(p)} <span class="meta">- ${esc(p.btLabel)}, ${p.hand==='R'?'right':'left'} hand bat</span></div>
      <div class="cols">${cols.map(c=>`<div>${bar(S(p)[c]??0,c)}</div>`).join('')}</div></div>`).join('');
  }
  $('#page').innerHTML=crumb(t.name,'Squad')+ctl+body;
}
const ROLEICON={opener:'OP',topOrderBat:'TOP',middleOrderBat:'MID',wicketkeeper:'WK',allRounder:'AR',seamFast:'FST',seamFastMedium:'FM',seamMedium:'MED',wristSpin:'WS',fingerSpin:'FS'};
const FORMDOT=f=>{const c=['#7a1d1d','#B23230','#c07a3a','#999','#7a9a3a','#2c7a2c','#1c5537'][f??3];return `<span title="form: ${FORMW_UI[f??3]}" style="display:inline-block;width:9px;height:9px;border-radius:50%;background:${c}"></span>`};
const FORMW_UI=['abysmal','poor','shaky','steady','good','strong','excellent'];
function miniBar(v,tip){return `<span title="${tip}: ${word(v)} (rank ${wIx(v)+1}/16)\n${SKILLTIP}"><span class="skbar" style="width:56px;height:8px"><i style="width:${foSkBar(v)}%"></i></span> <b class="sknum">${Math.round(v)}</b></span>`}
function cardsView(ps){
  const rows=ps.map((p,ix)=>{
    const openK=p.name, isOpen=!!squadView.open[openK];
    const tchips=(p.talents||[]).map(t=>`<span class="talchip" title="${ptal(t)}: ${TALTIPS[t]||''}">${ptal(t)}</span>`).join('');
    return `<div class="pcard">
     <div class="pcard-row ${ix%2?'alt':''}" onclick="squadView.open['${esc(openK)}']=!squadView.open['${esc(openK)}'];pgSquad()">
      <span class="rolechip" title="${prole(p.role)}">${ROLEICON[p.role]||'-'}</span>
      <span class="pname"><span title="${esc(p.nat)}">${flag(p.nat)}</span> <b>${esc(p.name)}</b>${p.keeper?' <span title="wicketkeeper">†</span>':''}${p.__y?' <span class="small">U20</span>':''}</span>
      <span class="pmeta"><span title="${EXPTIP}">${p.age|0} · ${esc((p.expWord||'').slice(0,9))}</span> <span title="${FORMTIP}">${FORMDOT(p.formIx)}</span>${p.fatigue==='tired'?' <span class="tiredchip" title="tired - recovers next match or with Rest">TIRED</span>':''}</span>
      <span class="pcol" title="Batting: ${word(aggBat(p))}\n${SKILLTIP}"><span class="collbl">BAT</span>${miniBar(aggBat(p),'Batting')}</span>
      <span class="pcol" title="Bowling: ${p.bowlType?word(aggBowl(p)):'does not bowl'}\n${SKILLTIP}"><span class="collbl">BWL</span>${p.bowlType?miniBar(aggBowl(p),'Bowling'):'<span class="small" style="opacity:.35">-</span>'}</span>
      <span class="pcol" title="Fielding: ${word(aggField(p))}\n${SKILLTIP}"><span class="collbl">FLD</span>${miniBar(aggField(p),'Fielding')}</span>
      <span class="ptal">${tchips}</span>
      <span class="n prat" title="overall rating">${p.rating}</span>
      <span class="caret">${isOpen?'▾':'▸'}</span>
     </div>
     ${isOpen?`<div class="pcard-detail">${summaryBlock(p)}${p.__y?`<div class="pad"><button onclick="promoteYouth(App.teamIx,'${esc(p.name)}')">Promote to seniors</button></div>`:''}</div>`:''}
    </div>`}).join('');
  return `<div class="panel"><h4>Squad <span style="font-weight:normal;font-size:9px">click a row for full skills &amp; training</span></h4><div class="pad" style="padding:4px 6px">${rows}</div></div>`;
}
function summaryBlock(p){
  return `<div class="pblock">
    <div class="hd">${playerLink(p)}${p.__y?`<span class="phasechip" title="Youth squad"> U20</span> <button style="font-size:9px;padding:1px 5px" onclick="promoteYouth(App.teamIx,&quot;${esc(p.name)}&quot;)">promote</button>`:''} <span class="meta">(${esc(p.nat)}) · ${prole(p.role)} · age ${p.age} · rating <b>${p.rating}</b></span></div>
    <div class="meta">${p.hand==='R'?'Right':'Left'} hand batsman | ${esc(p.btLabel)} · exp ${esc(p.expWord||p.exp)} · form ${esc(p.formWord)} · ${esc(p.fatigue)} · capt ${esc(p.capt)}${(p.talents&&p.talents.length)?' &nbsp;'+p.talents.map(t=>`<span class="talchip" title="${TALTIPS[t]||''}">${ptal(t)}</span>`).join(' '):''}</div>
    <div class="cols">
      <div>${bar(aggBat(p),'Batting')}<br>${bar(aggBowl(p),'Bowling')}<br>${bar(aggKeep(p),'Keeping')}</div>
      <div>${bar(aggEnd(p),'Endurance')}<br>${bar(aggTech(p),'Technique')}<br>${bar(S(p).power,'Power')}</div>
      <div>${bar(aggField(p),'Fielding')}<br><span class="sklbl">Training</span><select onchange="setTrain('${esc(p.name)}',this.value)" style="font-size:10px">${['none','Batting','Power','Rotation','Bowling','Discipline','Fielding','Keeping','Endurance','Rest'].map(k=>`<option ${p.trainFocus===k?'selected':''}>${k}</option>`).join('')}</select></div>
    </div></div>`;
}
const GRIDKEYS={Player:p=>p.name,Age:p=>p.age,Nat:p=>p.nat,BT:p=>shortBT(p),Role:p=>p.role,End:aggEnd,Bat:aggBat,Bowl:aggBowl,Tech:aggTech,Power:p=>S(p).power,Keep:aggKeep,Field:aggField,Exp:p=>p.exp,Fatg:p=>p.fatigue,Form:p=>p.formIx??3,Wage:p=>p.wage||0,Rating:p=>p.rating};
function gridSort(k){if(squadView.key===k)squadView.dir*=-1;else{squadView.key=k;squadView.dir=-1}
  if(App.page==='squad')pgSquad();}
function gridTable(ps){
  if(squadView.key&&GRIDKEYS[squadView.key]){const f=GRIDKEYS[squadView.key];
    ps=ps.slice().sort((a,b)=>{const x=f(a),y=f(b);return (x<y?-1:x>y?1:0)*squadView.dir})}
  const H=k=>`<th style="cursor:pointer" title="${TIPS[k]||k} - click to sort" onclick="gridSort('${k}')">${k}${squadView.key===k?(squadView.dir<0?' \u25BC':' \u25B2'):''}</th>`;
  return `<div class="panel"><h4>Overall grid <span style="font-weight:normal;font-size:9px">click a column to sort</span></h4><div class="pad"><table>
  <tr>${['Player','Age','Nat','BT','Role','End','Bat','Bowl','Tech','Power','Keep','Field'].map(H).join('')}<th>Capt</th>${['Exp','Fatg','Form','Rating'].map(H).join('')}</tr>
  ${ps.map(p=>`<tr><td>${playerLink(p)}</td><td>${p.age}</td><td>${esc(p.nat)}</td><td>${esc(shortBT(p))}</td><td>${prole(p.role)}</td>
   <td>${abbr(aggEnd(p))}</td><td>${abbr(aggBat(p))}</td><td>${abbr(aggBowl(p))}</td><td>${abbr(aggTech(p))}</td><td>${abbr(S(p).power)}</td><td>${abbr(aggKeep(p))}</td><td>${abbr(aggField(p))}</td>
   <td title="${TIPS.Capt}">${abbr(p.capt||30)}</td><td>${esc(p.expWord||p.exp)}</td><td>${esc(p.fatigue)}</td><td>${esc(p.formWord)}</td><td class="n">$${(p.wage||0).toLocaleString()}</td><td class="n">${p.rating}</td></tr>`).join('')}
  </table></div></div>`;
}
function shortBT(p){const m={'none':'-','seamFast':'RF','seamFastMedium':'RFM','seamMedium':'RM','wristSpin':'WS','fingerSpin':'FS','partTimeSeam':'pt-S','partTimeSpin':'pt-Sp'};
  let v=m[p.bowlTypeFull]||'-';if(p.hand==='L'&&v!=='-')v='L'+v.slice(1);return v}

// ---------- Players (browse all clubs) ----------
let playersClub=0;
function pgPlayers(){
  const t=GD.teams[playersClub];
  $('#page').innerHTML=crumb('Players','Browse')+
  `<div class="ctlrow"><span>Club:</span><select onchange="playersClub=+this.value;pgPlayers()">${GD.teams.map((x,i)=>`<option value="${i}" ${i===playersClub?'selected':''}>${esc(x.name)}</option>`).join('')}</select></div>`+
  gridTable(sortPlayers(t.players));
}

// ---------- Player details ----------
// the numbers cricket people think in, aggregated from the match history
function foSeasonNumbers(name){
  const h=App.playerHist[name]||[];let runs=0,balls=0,outs=0,inns=0,best=0,w=0,cr=0,cb=0;
  for(const e of h){
    if((e.bb||0)>0||e.o){inns++;runs+=e.rr||0;balls+=e.bb||0;if(e.o)outs++;if((e.rr||0)>best)best=e.rr||0;}
    w+=e.w||0;cr+=e.cr||0;cb+=e.cb||0;
  }
  return {matches:h.length,inns,runs,best,avg:outs?runs/outs:(inns?runs:null),sr:balls?100*runs/balls:null,
    wkts:w,bowlAvg:w?cr/w:null,econ:cb?cr/(cb/6):null,overs:cb};
}
function foSeasonLine(name){
  const n=foSeasonNumbers(name);if(!n.matches)return '';
  const bits=[];
  if(n.inns)bits.push(`${n.runs} runs${n.avg!=null?' @ '+n.avg.toFixed(1):''}${n.sr?' · SR '+n.sr.toFixed(0):''} · best ${n.best}`);
  if(n.overs)bits.push(`${n.wkts} wkt${n.wkts===1?'':'s'}${n.bowlAvg!=null?' @ '+n.bowlAvg.toFixed(1):''}${n.econ!=null?' · econ '+n.econ.toFixed(2):''}`);
  return bits.join(' &nbsp;·&nbsp; ');
}
