 'England':{fn:['Tom','Ben','Sam','Jos','Harry','Ollie','Jack','Will','Zak','Liam','James','Noah'],ln:['Wells','Taylor','Brown','Dawson','Clarke','Wright','Harrison','Bennett','Foster','Trott','Whitaker','Larkspur']},
 'Netherlands':{fn:['Daan','Pieter','Bram','Niels','Lars','Jasper','Sven','Wouter','Casper','Timo','Joost','Thijs','Ruben','Matthijs','Milan'],ln:['de Vries','Smit','Visser','van Dijk','de Boer','Kuiper','Bakker','van der Meer','Jansen','Nijhuis','Verhoeven','Veldman','Brandt','Hendriks','Vos','Kramer']},
 'West Indies':{fn:['Otis','Jason','Kemar','Andre','Shai','Nicholas','Romario','Kirk','Devon','Marlon','Fabian','Akeem'],ln:['Charles','Lewis','Joseph','Thomas','Simmons','Bishop','Greaves','Walcott','Providence','Cato','Forde','Alleyne']},
 'Afghanistan':{fn:['Rashid','Noor','Ibrahim','Rahmat','Naveen','Fazal','Gulbadin','Hashmat','Karim','Zahir','Mujeeb','Najib'],ln:['Zadran','Shah','Khan','Ahmadi','Naib','Omarzai','Hassan','Rahimi','Safi','Stanikzai','Habibi','Noori']},
 'Ireland':{fn:['Finn','Noah','Conor','Liam','Sean','Cian','Eoin','Declan','Rory','Patrick','Cormac','Ronan'],ln:["O'Brien",'Murphy','Kelly','Byrne','Walsh','Doyle','McCarthy','Gallagher','Kennedy','Lynch',"O'Connor",'Brennan']},
 'Zimbabwe':{fn:['Tendai','Blessing','Tinashe','Takudzwa','Brendan','Craig','Wesley','Regis','Kudzai','Tafadzwa','Munashe','Sean'],ln:['Moyo','Ncube','Dube','Sibanda','Mpofu','Nyathi','Marufu','Gumbo','Chirinda','Banda','Zhuwao','Masuku']}
