// ---------- Orders ----------
function bowlOpts(sel){
  const t=userTeam();
  const bs=t.players.filter(p=>p.bowlType&&(App.orders.showPT||!isPT(p)));
  return '<option value="">-</option>'+bs.map(p=>`<option ${sel===p.name?'selected':''} value="${esc(p.name)}">${esc(p.name)} (${esc(shortBT(p))})</option>`).join('');
}
function compilePlan(){
  const plan=new Array(50).fill(null);const tot={};const warns=[];
  for(const end of ['north','south']){
    for(const sp of App.orders.spells[end]){
      if(!sp.bowler||!sp.first||!sp.n)continue;
      const parity=end==='north'?1:0; // north = odd overs (1,3,..), display 1-based
      if(sp.first%2!==(end==='north'?1:0))warns.push(`${sp.bowler}: 1st over ${sp.first} is not a ${end} end over`);
      for(let k=0;k<sp.n;k++){
        const ov=sp.first+2*k;
        if(ov<1||ov>50)continue;
        if(plan[ov-1])warns.push(`Over ${ov}: double-booked (${plan[ov-1]} / ${sp.bowler})`);
        plan[ov-1]=sp.bowler;tot[sp.bowler]=(tot[sp.bowler]||0)+1;
      }
    }
  }
  for(const b in tot)if(tot[b]>10)warns.push(`${b}: ${tot[b]} overs planned (max 10)`);
  for(let o=0;o<49;o++)if(plan[o]&&plan[o]===plan[o+1])warns.push(`${plan[o]}: consecutive overs ${o+1}-${o+2}`);
  const covered=plan.filter(Boolean).length;
  if(covered<50)warns.push(`Only ${covered}/50 overs assigned - AI fills gaps`);
  App.orders.compiled=plan;App.orders.tot=tot;
  return{plan,tot,warns,covered};
}
function plannedBowler(inn,over){ // consumed by engine patch P1/P3; P16: per-team orders map
  if(typeof App==='undefined'||!UI.usePlan)return null;
  const O=(typeof ordersFor==='function')?ordersFor(inn.bowlTeam):null;
  if(!O)return null;
  const nm=O.compiled&&O.compiled[over];
  if(!nm)return null;
  return availableBowlers(inn).find(p=>p.name===nm)||null;
}
function spellRowsHTML(end){
  return App.orders.spells[end].map((sp,i)=>{
    const ph=sp.first<=10?'new':(sp.first>=41?'death':'mid');
    return `<div class="spellrow"><select onchange="App.orders.spells['${end}'][${i}].bowler=this.value;pgOrders()">${bowlOpts(sp.bowler)}</select>
    <span>1st</span><input type="number" min="1" max="50" value="${sp.first||''}" style="width:44px" onchange="App.orders.spells['${end}'][${i}].first=+this.value;pgOrders()">
    <span>#</span><input type="number" min="1" max="10" value="${sp.n||''}" style="width:38px" onchange="App.orders.spells['${end}'][${i}].n=+this.value;pgOrders()">
    <select onchange="App.orders.spells['${end}'][${i}].field=this.value"><option ${sp.field==='bal'?'selected':''} value="bal">balanced</option><option ${sp.field==='att'?'selected':''} value="att">attacking</option><option ${sp.field==='def'?'selected':''} value="def">defensive</option></select>
    <span class="phasechip">${ph}</span><button class="warn" onclick="App.orders.spells['${end}'].splice(${i},1);pgOrders()">x</button></div>`;
  }).join('')+`<button onclick="App.orders.spells['${end}'].push({bowler:'',first:${end==='north'?1:2},n:5,field:'bal'});pgOrders()">+ add spell</button>`;
}
const BOWLCOLS=['#22635F','#B23230','#2c7a2c','#C08A2E','#6a4a8f','#1c5537','#8f5a2d'];
function ordersTimeline(){
  const v=App.orders;const names=[...new Set(v.compiled.filter(Boolean))];
  const cells=v.compiled.map((nm,i)=>{const ci=names.indexOf(nm);
    return `<span title="over ${i+1}: ${nm||'AI decides'}" style="display:inline-block;width:14px;height:14px;margin:0 1px 1px 0;border:1px solid #99a;background:${nm?BOWLCOLS[ci%7]:'#eee'}"></span>`}).join('');
  const legend=names.map((nm,i)=>`<span class="small" style="margin-right:8px"><span style="display:inline-block;width:9px;height:9px;background:${BOWLCOLS[i%7]}"></span> ${esc(nm.split(' ').slice(-1)[0])} (${App.orders.tot[nm]||0})</span>`).join('');
  return `<div style="margin:5px 0">${cells}</div><div>${legend||'<span class="small">no overs planned - AI captain will decide</span>'}</div>`;
}
function applyPreset(kind){
  const t=userTeam();const xi=pickXI(t);
  let bs=xi.filter(p=>p.bowlType&&!isPT(p));
  if(kind==='pace')bs.sort((a,b)=>((typeClass(b.bowlType)==='pace')-(typeClass(a.bowlType)==='pace'))||((b.threat+b.control)-(a.threat+a.control)));
  else if(kind==='spin')bs.sort((a,b)=>((typeClass(b.bowlType)==='spin')-(typeClass(a.bowlType)==='spin'))||((b.threat+b.control)-(a.threat+a.control)));
  else bs.sort((a,b)=>(b.threat+b.control)-(a.threat+a.control));
  const[b1,b2,b3,b4,b5]=bs;if(!b5)return;
  App.orders.spells.north=[{bowler:b1.name,first:1,n:5,field:'att'},{bowler:b3.name,first:11,n:10,field:'bal'},{bowler:b5.name,first:31,n:5,field:'bal'},{bowler:b1.name,first:41,n:5,field:'def'}];
  App.orders.spells.south=[{bowler:b2.name,first:2,n:5,field:'att'},{bowler:b4.name,first:12,n:10,field:'bal'},{bowler:b2.name,first:32,n:5,field:'bal'},{bowler:b5.name,first:42,n:5,field:'def'}];
  pgOrders();
}
function suggestOrders(){
  const t=userTeam();const xi=pickXI(t);
  App.orders.batOrder=xi.map(p=>p.name);
  App.orders.captain=xi[0].name;
  App.orders.keeper=(xi.find(p=>p.keeper)||xi[0]).name;
  const bs=xi.filter(p=>p.bowlType&&!isPT(p)).sort((a,b)=>(b.threat+b.control)-(a.threat+a.control));
  const[b1,b2,b3,b4,b5]=bs;
  if(bs.length>=5){
    App.orders.spells.north=[{bowler:b1.name,first:1,n:5,field:'att'},{bowler:b3.name,first:11,n:10,field:'bal'},{bowler:b5.name,first:31,n:5,field:'bal'},{bowler:b1.name,first:41,n:5,field:'def'}];
    App.orders.spells.south=[{bowler:b2.name,first:2,n:5,field:'att'},{bowler:b4.name,first:12,n:10,field:'bal'},{bowler:b2.name,first:32,n:5,field:'bal'},{bowler:b5.name,first:42,n:5,field:'def'}];
  }
  pgOrders();
}
function moveBat(i,d){const o=App.orders.batOrder;const j=i+d;if(j<0||j>=o.length)return;
  [o[i],o[j]]=[o[j],o[i]];pgOrders();}
function autoArrange(){
  const t=userTeam();const xi=pickXI(t);
  const B=App.orders.budget||{};
  const opts=t.players.filter(p=>p.bowlType&&(App.orders.showPT||!isPT(p))).filter(p=>(B[p.name]|0)>0);
  const left={};let tot=0;for(const p of opts){left[p.name]=Math.min(10,B[p.name]|0);tot+=left[p.name]}
  if(tot!==50){App.orders._budgetWarn='Budgets total '+tot+' - need exactly 50.';pgOrders();return}
  App.orders._budgetWarn='';
  const isPace=p=>typeClass(p.bowlType)==='pace';
  const nbVal=p=>(0.6*p.threat+0.4*p.control)+((p.talents||[]).includes('newBallSpecialist')?8:0)+(isPace(p)?6:0);
  const dVal=p=>(0.5*p.control+0.5*p.threat)+((p.talents||[]).includes('deathSpecialist')?9:0);
  const mVal=p=>(0.5*p.threat+0.5*p.control)+(!isPace(p)?7:0);
  const pool=opts.slice();
  const take=(scoreFn,excl)=>{const c=pool.filter(p=>left[p.name]>0&&!excl.includes(p.name)).sort((a,b)=>scoreFn(b)-scoreFn(a))[0];return c?c.name:null};
  const a=new Array(51).fill(null); // 1-indexed overs
  const nb1=take(nbVal,[]),nb2=take(nbVal,[nb1]);
  const d1=take(dVal,[]),d2=take(dVal,[d1]);
  const assign=(ov,nm)=>{if(nm&&left[nm]>0){a[ov]=nm;left[nm]--;return true}return false};
  for(let o=1;o<=9;o+=2)if(!assign(o,nb1))break;
  for(let o=2;o<=10;o+=2)if(!assign(o,nb2))break;
  for(let o=50;o>=42;o-=2)if(!assign(o,d1))break;
  for(let o=49;o>=41;o-=2)if(!assign(o,d2))break;
  // middle + gaps: greedy by mVal, keeping same-end continuity for spell shape
  for(const end of [1,0]){ // odd end first
    let cur=null;
    for(let o=11+(end?0:1);o<=40;o+=2){
      if(a[o])continue;
      if(cur&&left[cur]>0){a[o]=cur;left[cur]--;continue}
      cur=take(mVal,[a[o-1]||'']);if(!assign(o,cur))cur=null;
    }}
  for(let o=1;o<=50;o++){if(a[o])continue;
    const nm=take(mVal,[a[o-1]||'',a[o+1]||'']);if(!assign(o,nm)){const any=take(()=>1,[]);assign(o,any)}}
  // derive spells per end from contiguous runs
  const spells={north:[],south:[]};
  for(const end of ['north','south']){
    const start=end==='north'?1:2;
    let run=null;
    for(let o=start;o<=50;o+=2){
      const nm=a[o];
      if(run&&run.bowler===nm){run.n++;continue}
      if(run)spells[end].push(run);
      run=nm?{bowler:nm,first:o,n:1,field:o<=10?'att':(o>=41?'def':'bal')}:null;
    }
    if(run)spells[end].push(run);
  }
  App.orders.spells=spells;
  pgOrders();
}
function budgetStep(nm,d){App.orders.budget=App.orders.budget||{};
  const v=Math.max(0,Math.min(10,(App.orders.budget[nm]|0)+d));App.orders.budget[nm]=v;pgOrders();}
function budgetFromSpells(){const v=compilePlan();App.orders.budget={};for(const k in v.tot)App.orders.budget[k]=v.tot[k];}
function ensureTactics(){
  if(!App.orders.phaseIntent)App.orders.phaseIntent={pp:0,mid:0,death:1};
  if(!App.orders.fieldPlan)App.orders.fieldPlan={pp:'bal',mid:'bal',death:'att'};
}
function gridState(){ensureTactics();
  if(!App.orders.grid){
    // seed grid from compiled plan if any
    const v=compilePlan();
    App.orders.grid=new Array(51).fill(null);
    (App.orders.compiled||[]).forEach((nm,o)=>{if(nm)App.orders.grid[o+1]=nm});
    const names=[...new Set(App.orders.grid.filter(Boolean))];
    App.orders.gridBowlers=names.length?names:null;
  }
  if(!App.orders.gridBowlers){
    const t=userTeam();
    App.orders.gridBowlers=t.players.filter(p=>p.bowlType&&!isPT(p)).sort((a,b)=>(b.threat+b.control)-(a.threat+a.control)).slice(0,5).map(p=>p.name);
  }
  return App.orders;
}
function gridToSpells(){
  const a=App.orders.grid;
  const spells={north:[],south:[]};
  for(const end of ['north','south']){
    const start=end==='north'?1:2;let run=null;
    for(let o=start;o<=50;o+=2){
      const nm=a[o];
      if(run&&run.bowler===nm){run.n++;continue}
      if(run&&run.bowler)spells[end].push(run);
      run=nm?{bowler:nm,first:o,n:1,field:o<=10?'att':(o>=41?'def':'bal')}:null;
    }
    if(run&&run.bowler)spells[end].push(run);
  }
  App.orders.spells=spells;compilePlan();
}
