  if(App.pending){const me=userTeam().name,them=App.pending.home===me?App.pending.away:App.pending.home;
    const past=App.results.filter(r=>(r.home===me&&r.away===them)||(r.home===them&&r.away===me));
    const w=past.filter(r=>r.result.winner===me).length;
    if(past.length)h2h=` · H2H vs ${esc(them)}: ${w}–${past.length-w}`;}
  const condBanner=App.pending?`<div class="panel" style="border-left:4px solid #C08A2E"><div class="pad"><b>Conditions at ${esc(App.pending.ground)}:</b> <span title="${pitchTip(App.pending.pitch)}">${esc(App.pending.pitch)} pitch</span> · forecast <span title="${wxTip(App.pending.weather)}">${esc(App.pending.weather)}</span>${h2h} <span class="small">- ${App.pending.pitch==='dry'?'spin grips from mid-innings':App.pending.pitch==='green'?'seam help, big new-ball window':App.pending.pitch==='flat'?'a road, pack the batting':App.pending.pitch==='slow'?'sixes die, rotate instead':App.pending.pitch==='cracked'?'variable bounce all day':App.pending.pitch==='twoPaced'?'timing is hard here':'a fair surface'}.</span></div></div>`:'';
  // batting: 11 dropdowns with duplicate detection
  const names=xi.map(p=>p.name);
  const dupes={};App.orders.batOrder.slice(0,11).forEach(n=>dupes[n]=(dupes[n]||0)+1);
  const batRows=Array.from({length:11},(_,i)=>{
    const nm=App.orders.batOrder[i];const p=byName(nm);
    return `<div class="ctlrow" style="margin:1px 0">
      <span class="n small" style="width:16px;color:#999">${i+1}</span>
      <select style="${dupes[nm]>1?'border-color:#B23230;background:#fbe9e7':''}" onchange="App.orders.batOrder[${i}]=this.value;pgOrders()">${names.map(n=>`<option ${nm===n?'selected':''}>${esc(n)}</option>`).join('')}</select>
      ${p?`${sdot(aggBat(p),'Batting')}<span class="small" title="${prole(p.role)}">${ROLEICON[p.role]||''}</span>${p.keeper?' †':''}`:''}
      <input type="radio" name="capt" title="captain" ${App.orders.captain===nm?'checked':''} onchange="App.orders.captain='${esc(nm)}';pgOrders()">
      <input type="radio" name="wkpr" title="wicketkeeper" ${App.orders.keeper===nm?'checked':''} onchange="App.orders.keeper='${esc(nm)}';pgOrders()">
    </div>`}).join('');
  const dupWarn=Object.values(dupes).some(n=>n>1)?'<div class="warntxt">⚠ Duplicate batter in the order - fix before saving.</div>':'';
  const batLegend=`<div class="ctlrow small" style="margin:0 0 2px;color:#777"><span style="width:16px"></span><span style="flex:1"></span><span title="captain">C</span><span title="wicketkeeper">WK</span></div>
   <div class="small" style="margin-bottom:3px">Captain: <b>${esc(App.orders.captain||'-')}</b> · Wicketkeeper: <b>${esc(App.orders.keeper||'-')}</b> <span title="The designated keeper takes the gloves for stumpings and keeps catches behind the stumps, whatever his listed role.">ⓘ</span></div>`;
  // bowling grid
  const allBowlers=t.players.filter(p=>p.bowlType&&(App.orders.showPT||!isPT(p)));
  const gb=App.orders.gridBowlers;
