  const press=M.target?(((M.target-inn.runs)/Math.max(0.5,(foBallCap()-inn.legal)/6))-(inn.legal>0?inn.runs/(inn.legal/6):5)):0;
  const pressWord=!M.target?'-':press>1.5?'severe':press>0.5?'building':press>-0.5?'even':'in control';
  // this over strip
  const cur=[];for(const L of M.log){if(L.inn!==M.inns||L.mile)continue;
    if(Math.floor(parseFloat(L.no))===Math.floor(Math.max(0,inn.legal-1)/6))cur.unshift(L);else break}
  const strip=cur.map(L=>{const c=L.out==='4'?'r4':L.out==='6'?'r6':isWkt(L.out)?'W':(['wide','noball'].includes(L.out)?'ex':'');
    const s=L.out==='4'?'4':L.out==='6'?'6':isWkt(L.out)?'W':L.out==='dot'?'·':(['1','2','3'].includes(L.out)?L.out:'+');
    return `<span class="tob ${c}">${s}</span>`}).join('');
