let netsState={batClub:0,bat:null,bowlClub:0,bowl:null,n:100,over:20,faced:30,intent:0,pitch:'balanced',field:'bal',weather:'Sunny',seed:7,res:null};
function runNets(batP,bowlP,n,opt){ // exposed for audit
  const r=rng(opt.seed>>>0);const counts={};let runs=0,legal=0,wkts=0;
  const ph=opt.over<10?'pp':(opt.over>=40?'death':'mid');
  for(let i=0;i<n;i++){
    const d=ballDist(batP,bowlP,ph,opt.faced,opt.intent,0,opt.pitch,opt.field,opt.over,{weather:(opt.weather||'sunny').toLowerCase(),pship:0,chase:false,bballs:12});
    const x=r();let c=0,out='dot';
    for(const k in d){c+=d[k];if(x<=c){out=k;break}}
    counts[out]=(counts[out]||0)+1;
    if(['1','2','3'].includes(out))runs+=+out;
    else if(out==='4')runs+=4;else if(out==='6')runs+=6;
    else if(['wide','noball','bye','legbye'].includes(out))runs+=1;
    if(out!=='wide'&&out!=='noball')legal++;
    if(isWkt(out))wkts++;
  }
  return{counts,runs,legal,wkts,n};
}
function netsSel(kind){
  const club=netsState[kind+'Club'];const t=GD.teams[club];
  const pool=kind==='bowl'?t.players.filter(p=>p.bowlType):t.players;
  if(!pool.find(p=>p.name===netsState[kind]))netsState[kind]=pool[0].name;
  return `<select onchange="netsState.${kind}Club=+this.value;netsState.${kind}=null;pgNets()">${GD.teams.map((x,i)=>`<option value="${i}" ${i===club?'selected':''}>${esc(x.name)}</option>`).join('')}</select>
   <select onchange="netsState.${kind}=this.value;pgNets()">${pool.map(p=>`<option ${netsState[kind]===p.name?'selected':''}>${esc(p.name)}</option>`).join('')}</select>`;
}
function pgNets(){
  for(const kind of ['bat','bowl']){const club=netsState[kind+'Club'];const t=GD.teams[club];
    const pool=kind==='bowl'?t.players.filter(p=>p.bowlType):t.players;
    if(!pool.find(p=>p.name===netsState[kind]))netsState[kind]=pool[0].name;}
  const batP=findPlayer(netsState.bat||'')?.p||null, bowlP=findPlayer(netsState.bowl||'')?.p||null;
  let results='<div class="small">Set the session up and press Bowl.</div>';
  if(netsState.res){
    const R=netsState.res;
    const agg={dot:0,'1':0,'2':0,'3':0,'4':0,'6':0,wicket:0,extras:0};
    const dis={};
    for(const k in R.counts){
      if(isWkt(k)){agg.wicket+=R.counts[k];dis[k]=R.counts[k]}
      else if(['wide','noball','bye','legbye'].includes(k))agg.extras+=R.counts[k];
      else agg[k]=(agg[k]||0)+R.counts[k];
    }
    const COL={dot:'#9aa79c','1':'#7cb87c','2':'#5aa05a','3':'#3f8f3f','4':'#22635F','6':'#1c5537',wicket:'#B23230',extras:'#C08A2E'};
    const total=R.n;let a0=-Math.PI/2;let paths='';let legend='';
    for(const k of ['dot','1','2','3','4','6','wicket','extras']){
      const v=agg[k];if(!v)continue;
      const a1=a0+2*Math.PI*v/total;
      const large=(a1-a0)>Math.PI?1:0;
      const x0=90+80*Math.cos(a0),y0=90+80*Math.sin(a0),x1=90+80*Math.cos(a1),y1=90+80*Math.sin(a1);
      paths+=(v===total)?`<circle cx="90" cy="90" r="80" fill="${COL[k]}"/>`
        :`<path d="M90,90 L${x0.toFixed(1)},${y0.toFixed(1)} A80,80 0 ${large} 1 ${x1.toFixed(1)},${y1.toFixed(1)} Z" fill="${COL[k]}" stroke="#fff" stroke-width="1"/>`;
      const KN={dot:'dot',wicket:'wicket',extras:'extras'};legend+=`<tr><td><span style="display:inline-block;width:10px;height:10px;background:${COL[k]}"></span> ${KN[k]||k+' runs'}</td><td class="n">${v}</td><td class="n">${(100*v/total).toFixed(1)}%</td></tr>`;
      a0=a1;
    }
    const sr=R.legal?100*R.runs/R.legal:0;
    const bpd=R.wkts?(R.legal/R.wkts).toFixed(1):'-';
    const disTxt=Object.entries(dis).sort((a,b)=>b[1]-a[1]).map(([k,v])=>`${DFULL[k]} ${v}`).join(', ')||'none';
    results=`<div class="grid2"><div class="col" style="max-width:200px"><svg viewBox="0 0 180 180" width="180" height="180">${paths}</svg></div>
    <div class="col"><table><tr><th>Outcome</th><th class="n">Balls</th><th class="n">%</th></tr>${legend}</table></div>
    <div class="col"><table class="kv">
      <tr><td>Deliveries</td><td>${R.n} (${R.legal} legal)</td></tr>
      <tr><td>Runs</td><td><b>${R.runs}</b> (SR ${sr.toFixed(1)})</td></tr>
      <tr><td>Dismissals</td><td><b>${R.wkts}</b> (${bpd} balls per dismissal)</td></tr>
      <tr><td>How out</td><td class="small">${esc(disTxt)}</td></tr>
      <tr><td>Dot %</td><td>${(100*(agg.dot||0)/Math.max(1,R.legal)).toFixed(1)}%</td></tr>
      <tr><td>Boundary runs</td><td>${4*(agg['4']||0)+6*(agg['6']||0)} of ${R.runs}</td></tr>
    </table></div></div>`;
  }
  let strengths='';
  if(batP&&bowlP){
    const ctx={faced:netsState.faced,over:netsState.over,pitch:netsState.pitch,weather:netsState.weather.toLowerCase(),chase:false,rrDef:0,pship:0};
    const d=ballDist(batP,bowlP,netsState.over<10?'pp':(netsState.over>=40?'death':'mid'),netsState.faced,netsState.intent,0,netsState.pitch,netsState.field,netsState.over,{weather:netsState.weather.toLowerCase(),pship:0,chase:false,bballs:12});
    let eSR=0,pW=0,pDot=0,pB=0;
    for(const k in d){if(['1','2','3'].includes(k))eSR+=(+k)*d[k];else if(k==='4')eSR+=4*d[k],pB+=d[k];else if(k==='6')eSR+=6*d[k],pB+=d[k];else if(isWkt(k))pW+=d[k];else if(k==='dot')pDot=d[k]}
    strengths=`<div class="panel"><h4>Matchup strength - this exact situation</h4><div class="pad"><div class="grid2">
      <div class="col">${meter(effBat(batP,bowlP,ctx),'Batter')}${meter(effBowl(batP,bowlP,ctx),'Bowler')}</div>
      <div class="col small"><b>True per-ball odds (exact, not sampled):</b><br>
        expected SR ${(100*eSR).toFixed(1)} &nbsp;·&nbsp; dismissal ${(100*pW).toFixed(2)}%/ball (1 in ${(1/Math.max(1e-6,pW)).toFixed(0)})<br>
        dot ${(100*pDot).toFixed(1)}% &nbsp;·&nbsp; boundary ${(100*pB).toFixed(1)}%</div>
    </div></div></div>`;
  }
  $('#page').innerHTML=crumb('Nets','Practice session')+strengths+
  `<div class="panel"><h4>Session setup</h4><div class="pad">
    <div class="ctlrow"><span style="width:60px"><b>Batter</b></span>${netsSel('bat')}</div>
    <div class="ctlrow"><span style="width:60px"><b>Bowler</b></span>${netsSel('bowl')}</div>
    <div class="ctlrow">
      <span>Balls:</span><select onchange="netsState.n=+this.value">${[10,100,1000].map(n=>`<option ${netsState.n===n?'selected':''}>${n}</option>`).join('')}</select>
      <span>Over:</span><select onchange="netsState.over=+this.value"><option value="2" ${netsState.over===2?'selected':''}>2 (new ball)</option><option value="20" ${netsState.over===20?'selected':''}>20 (middle)</option><option value="35" ${netsState.over===35?'selected':''}>35 (grip)</option><option value="45" ${netsState.over===45?'selected':''}>45 (death)</option></select>
      <span>Batter is:</span><select onchange="netsState.faced=+this.value"><option value="0" ${netsState.faced===0?'selected':''}>new (0 faced)</option><option value="10" ${netsState.faced===10?'selected':''}>getting in (10)</option><option value="30" ${netsState.faced===30?'selected':''}>set (30)</option></select>
      <span>Intent:</span><select onchange="netsState.intent=+this.value">${[[-1,'Defend'],[0,'Normal'],[1,'Attack'],[2,'Launch']].map(([v,l])=>`<option value="${v}" ${netsState.intent===v?'selected':''}>${l}</option>`).join('')}</select>
      <span>Pitch:</span><select onchange="netsState.pitch=this.value">${['balanced','flat','green','dry','slow','cracked','twoPaced'].map(p=>`<option ${netsState.pitch===p?'selected':''}>${p}</option>`).join('')}</select>
      <span>Field:</span><select onchange="netsState.field=this.value">${[['bal','balanced'],['att','attacking'],['def','defensive']].map(([v,l])=>`<option value="${v}" ${netsState.field===v?'selected':''}>${l}</option>`).join('')}</select>
      <span>Weather:</span><select onchange="netsState.weather=this.value">${WXLIST.map(w=>`<option ${netsState.weather===w?'selected':''}>${w}</option>`).join('')}</select>
      <span>Seed:</span><input type="number" value="${netsState.seed}" style="width:60px" onchange="netsState.seed=+this.value">
      <button class="primary" onclick="const b=findPlayer(netsState.bat).p,w=findPlayer(netsState.bowl).p;netsState.res=runNets(b,w,netsState.n,{over:netsState.over,faced:netsState.faced,intent:netsState.intent,pitch:netsState.pitch,field:netsState.field,seed:netsState.seed});pgNets()">Bowl</button>
    </div>
    ${batP&&bowlP?`<div class="small">${esc(batP.name)} (bat ${word(batP.bat)}, vs ${typeClass(bowlP.bowlType)==='pace'?'pace '+word(batP.vsPace):'spin '+word(batP.vsSpin)}) faces ${esc(bowlP.name)} (${esc(bowlP.btLabel)}, threat ${word(bowlP.threat)}, control ${word(bowlP.control)}). Same seed replays the identical session.</div>`:''}
  </div></div>
  <div class="panel"><h4>Results</h4><div class="pad">${results}</div></div>`;
}
