    const tr=(App.trainingReports&&App.trainingReports[0])?`<div class="small" style="margin-top:4px"><b>Training:</b> ${(App.trainingReports[0].gains.slice(0,3).map(esc).join('; ')||'no skill gains this round')}</div>`:'';
    App._digest=`<div class="panel" style="border-left:4px solid var(--blue)"><h4>Round ${S.round} digest</h4><div class="pad">${digest}<div class="small" style="margin-top:3px"><b>Finance:</b> ${esc(App.fin.lastRoundFinanceSummary.summary)} · bank ${money(App.fin.bank)} · ${esc(App.fin.debtWarningLevel)}</div>${tr}</div></div>`;
