  function roleNoteObj(p){
    const sk=S(p);let best='Squad role',sec='Cover',risk='No major red flag',cond='Balanced pitches';
    if(p.keeper){best='Wicketkeeper-batter';sec=aggBat(p)>62?'Top-seven keeper':'Keeper cover';risk=sk.keeping<55?'Glovework may cost chances':'Keeping load creates fatigue';cond='Spin-friendly pitches if stumping is strong'}
    else if(p.role==='allRounder'){best='Balance all-rounder';sec=isSpin(p)?'Spin option':'Seam option';risk=aggBat(p)<45?'Can lengthen the tail':aggBowl(p)<45?'May be a fifth-bowler risk':'Role overload';cond=isSpin(p)?'Dry or slow surfaces':'Green/overcast if seam skill is strong'}
    else if(p.bowlTypeFull&&p.bowlTypeFull!=='none'){best=isPace(p)?(sk.moveTurn>sk.economy?'New-ball seamer':'Seamer'):(sk.wicket>sk.economy?'Attacking spinner':'Spinner');sec=(p.talents||[]).includes('deathSpecialist')?'Death overs':'Middle overs';risk=sk.stamina<45?'Long spells may tire him':sk.discipline<45?'Extras risk under pressure':'Limited batting';cond=isPace(p)?'Green, overcast, humid or misty':'Dry, slow or cracked'}
    else{best=p.role==='opener'?'Opening batter':p.role==='topOrderBat'?'No. 3 / top-order anchor':'Middle-order batter';sec=sk.power>65?'Late-over hitter':sk.rotation>65?'Strike-rotation specialist':'Stability option';risk=sk.vsPace<45?'Vulnerable to new-ball pace':sk.vsSpin<45?'Can stall against spin':sk.temperament<45?'Collapse risk under pressure':'Selection depends on role balance';cond=sk.vsSpin>sk.vsPace?'Dry/spin conditions':'Pace-friendly conditions'}
    return {best,secondary:sec,risk,conditions:cond,note:`${best}. ${cond}. Risk: ${risk}.`};
  }
  window.foRoleNoteObj=roleNoteObj;
